252			 * it. The exit code is still 1 and the stage is still named, so nothing
253			 * a defect used to be scored as has changed.
254			 */
255			const message = error instanceof Error ? error.message : String(error);
256			state.rows.push(
257				Object.freeze({ name, status: 'defect' as const, reason: message, startedAt, endedAt }),
258			);
259			state.halted = Object.freeze({ stage: name, status: 'defect' as const });
260			state.defect = Object.freeze({ stage: name, message });
261			return null;
262		}
263	}
264	
265	/** The stage order with the declarations each stage is handed, and nothing run. */
266	export function runStagePlan(
267		flags: Readonly<Record<string, readonly string[]>>,
268	): readonly RunStagePlanRow[] {
269		return Object.freeze(
270			RUN_STAGES.map((name) =>
271				Object.freeze({
272					name,
273					forwards: Object.freeze(
274						RUN_STAGE_FLAGS[name].filter((flag) => flags[flag] !== undefined),
275					),
276				}),
277			),
278		);
279	}
280	
281	/**
282	 * Run all nine stages, or state which one stopped the run.
283	 *
284	 * The stages are composed here in order and nowhere else. Each one receives
285	 * the declarations its own command would give it, which is what makes the
286	 * refusing defaults survive the chain: nothing is widened on the way through.
287	 */
288	export async function runFullPipeline(declarations: RunDeclarations): Promise<RunRecord> {
289		const stagePlan = runStagePlan(declarations.flags);
290		const application = displayPath(declarations.appRoot);
291		const lane = displayPath(declarations.out);
292		if (declarations.dryRun)
293			return Object.freeze({
294				schema: RUN_SCHEMA,
295				flow: 'run' as const,
296				outcome: 'not-run' as const,
297				exitCode: EXIT_PROCEEDED,
298				application,
299				lane,
300				dryRun: true,
301				stagePlan,
302				stages: Object.freeze([]),
303				report: Object.freeze({
304					status: 'not-yet-emitted' as const,
305					slot: RUN_COVERAGE_REPORT_SLOT,
306				}),
307				notEstablished: Object.freeze([
308					'--dry-run was declared, so no stage ran. Nothing here establishes what any of them would have recorded, and nothing was written into the lane.',
309					...RUN_NOT_ESTABLISHED,
310				]),
311			});
312		const state: RunState = { rows: [], halted: null, refusal: null, defect: null };
313		const analysis = await runStage(state, 'analyze', () =>
314			analyzeApplication(declarations.appRoot),
315		);
316		await runStage(state, 'ingest', () =>
317			ingestApplicationSource(declarations.sourceRoot, declarations.ingest),
318		);
319		await runStage(state, 'license-at-pin', async () => {
320			const frontendRoot = declarations.ingest.frontendRoot ?? '.';
321			const manifest = path.join(declarations.sourceRoot, frontendRoot, 'package.json');
322			return readLicenceAtPin(
323				declarations.sourceRoot,
324				(await fileExists(manifest)) ? manifest : null,
325				declarations.licence,
326			);
327		});
328		await runStage(state, 'era-cell', () =>
329			establishEraCell(declarations.appRoot, declarations.eraCell),
330		);
331		const planned = await runStage(state, 'plan', () =>
332			planApplication({
333				appRoot: declarations.appRoot,
334				angular: declarations.angular,
335				react: declarations.react,
336			}),
337		);
338		const applied = await runStage(state, 'apply', async () => {
339			if (planned === null || analysis === null)
340				throw new Error(
341					'run: the apply stage was reached without a plan. This is a defect in the chaining rather than a refusal: the stage order guarantees a plan before an apply.',
342				);
343			const changeset = await applyPlan(planned.plan, {
344				appRoot: declarations.appRoot,
345				out: declarations.out,
346				materialize: declarations.materialize,
347			});
348			const composition = await composeLane(
349				declarations.appRoot,
350				declarations.out,
351				planned.plan.lineage,
352				analysis.builder,
353			);
354			await writeLaneFiles(declarations.out, composition);
355			return {
356				applied: changeset,
357				laneComposition: {
358					...composition,
359					files: composition.files.map(({ source: _source, ...rest }) => rest),
360				},
361			};
362		});
363		await runStage(state, 'install', () =>
364			runLaneInstall(
365				declarations.out,
366				declarations.install,
367				process.env,
368				applied?.laneComposition.composed === true ? 'resolve' : 'replay',
369			),
370		);
371		const built = await runStage(state, 'build', () => runLaneBuild(declarations.out));
372		await runStage(state, 'witness', () =>
373			runLaneWitness({
374				application: path.basename(declarations.appRoot),
375				sourceRoot: declarations.appRoot,
376				laneBuild: path.join(declarations.out, built?.outDirectory ?? 'dist'),
377			}),
378		);
379		const halted = state.halted;
380		const exitCode =
381			halted === null ? EXIT_PROCEEDED : halted.status === 'refused' ? EXIT_REFUSAL : EXIT_DEFECT;
382		return Object.freeze({
383			schema: RUN_SCHEMA,
384			flow: 'run' as const,
385			outcome:
386				halted === null
387					? ('proceeded' as const)
388					: halted.status === 'refused'
389						? ('refused' as const)
390						: ('defect' as const),
391			exitCode,
392			application,
393			lane,
394			dryRun: false,
395			stagePlan,
396			stages: Object.freeze([...state.rows]),
397			...(state.refusal === null ? {} : { refusal: state.refusal }),
398			...(state.defect === null ? {} : { defect: state.defect }),
399			report: Object.freeze({
400				status: 'not-yet-emitted' as const,
401				slot: RUN_COVERAGE_REPORT_SLOT,
402			}),
403			notEstablished: RUN_NOT_ESTABLISHED,
404		});
405	}
406	
407	const STAGE_COLUMN = Math.max(...RUN_STAGES.map((name) => name.length)) + 2;
408	
409	function renderStagePlan(plan: readonly RunStagePlanRow[]): readonly string[] {
410		return plan.map(
411			(row, index) =>
412				`  ${String(index + 1)}. ${row.name.padEnd(STAGE_COLUMN)}${
413					row.forwards.length === 0
414						? 'no declaration from this command line'
415						: row.forwards.join(' ')
416				}`,
417		);
418	}
419	
420	/** The run as an operator reads it: the stage table, then whatever stopped it. */
421	export function renderRun(record: RunRecord): string {
422		const lines = [`application: ${record.application}`, `lane: ${record.lane}`, ''];
423		if (record.dryRun) {
424			lines.push('dry run: the stage order and the declarations each stage would be given.');
425			lines.push('');
426			lines.push(...renderStagePlan(record.stagePlan));
427			lines.push('');
428			lines.push('No stage ran and nothing was written into the lane.');
429		} else {
430			for (const row of record.stages)
431				lines.push(
432					`  ${row.name.padEnd(STAGE_COLUMN)}${row.status.padEnd(10)}${row.reason ?? ''}`,
433				);
434			lines.push('');
435			lines.push(
436				record.outcome === 'proceeded'
437					? `all ${String(record.stages.length)} stage(s) proceeded.`
438					: record.outcome === 'refused'
439						? `stopped at ${record.refusal?.stage ?? ''}.`
440						: `stopped at ${record.defect?.stage ?? ''} with a defect.`,
441			);
442		}
443		lines.push('');
444		if (record.refusal !== undefined) lines.push(renderRefusal(record.refusal));
445		if (record.defect !== undefined) {
446			lines.push(`defect: ${record.defect.stage}`);
447			lines.push('');
448			lines.push(record.defect.message);
449			lines.push('');
450		}
451		lines.push(`report: ${record.report.status} (${record.report.slot})`);
452		lines.push('');
453		for (const line of record.notEstablished) lines.push(`not established: ${line}`);
454		return `${lines.join('\n')}\n`;
455	}
