/**
 * `report:coverage`: the coverage pair, re-derived from the verified package.
 *
 * It is the same shape `report:enterprise` has, for the same reason: the trust
 * package is verified before anything is read out of it, the support matrix
 * comes from the one guarded derivation rather than a second count, and
 * `--verify-only` refuses to write so a reviewer can check the published pair
 * without touching it.
 *
 * The matrix is read through `readSupportedMatrix`, which is the same path the
 * `supported-matrix` flow uses. That is deliberate: a coverage report that
 * counted applications for itself could disagree with the matrix an operator is
 * allowed to quote, and two surfaces disagreeing about how many applications
 * were proven is the failure this document exists to make impossible.
 */

import { readFile, writeFile } from 'node:fs/promises';
import * as path from 'pathe';
import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
import { buildCapabilityCoverage } from '../../../core/src/receipts/capability-coverage.ts';
import {
	COVERAGE_REPORT_JSON,
	COVERAGE_REPORT_MARKDOWN,
	deriveCoverageSurfaces,
} from '../../../trust/src/coverage-report.ts';
import { readSupportedMatrix } from './matrix.ts';

export interface CoverageReportOptions {
	rootDir?: string;
	outputDir: string;
	verifyOnly: boolean;
	environment?: NodeJS.ProcessEnv;
}

export interface CoverageReportResult {
	result: 'pass';
	mode: 'generated' | 'verified';
	trustDigest: string;
	machineArtifact: string;
	humanDocument: string;
	machineArtifactSha256: string;
	humanDocumentSha256: string;
	coverageDigest: string;
	certification: 'not-certified';
}

export async function runCoverageReport(
	options: CoverageReportOptions,
): Promise<CoverageReportResult> {
	const root = path.resolve(options.rootDir ?? '.');
	const output = path.resolve(root, options.outputDir);
	const reading = await readSupportedMatrix({
		rootDir: options.rootDir,
		trustDir: options.outputDir,
		environment: options.environment,
	});
	const derived = await deriveCoverageSurfaces({
		root,
		output,
		matrix: reading.matrix,
		capabilityCoverage: buildCapabilityCoverage(),
	});
	const jsonPath = path.join(output, COVERAGE_REPORT_JSON);
	const markdownPath = path.join(output, COVERAGE_REPORT_MARKDOWN);
	if (options.verifyOnly) {
		const published = JSON.parse(await readFile(jsonPath, 'utf8')) as unknown;
		if (canonicalize(published) !== canonicalize(derived.report))
			throw new Error(
				`${COVERAGE_REPORT_JSON} does not match independent re-derivation from the canonical receipts`,
			);
		if ((await readFile(markdownPath, 'utf8')) !== derived.markdown)
			throw new Error(
				`${COVERAGE_REPORT_MARKDOWN} does not match independent re-derivation from the canonical receipts`,
			);
	} else {
		await writeFile(jsonPath, `${JSON.stringify(derived.report, null, 2)}\n`);
		await writeFile(markdownPath, derived.markdown);
	}
	return {
		result: 'pass',
		mode: options.verifyOnly ? 'verified' : 'generated',
		trustDigest: reading.trustDigest,
		machineArtifact: path.join(options.outputDir, COVERAGE_REPORT_JSON),
		humanDocument: path.join(options.outputDir, COVERAGE_REPORT_MARKDOWN),
		machineArtifactSha256: sha256(await readFile(jsonPath)),
		humanDocumentSha256: sha256(await readFile(markdownPath)),
		coverageDigest: derived.report.integrity.canonicalDigest,
		certification: 'not-certified',
	};
}

